// The whole application, wired the way startup wires it:
await using var app = await ZeroTestApplication.Create()
    .AddServices(services => services.AddScoped<IInvoiceStore, FakeInvoiceStore>())
    .AddHandler<CreateInvoice, int, CreateInvoiceHandler>()
    .AddConfiguration(("Mail:Host", "smtp.example.com"))
    .AddValidator(new CreateInvoiceValidator())
    .AddModule(new MyApp.Module())
    .BuildAsync();

var result = await app.SendAsync(new CreateInvoice("", 0m));

result.ShouldFailWithCodes("invoice.reference", "invoice.amount");

// One handler, through the real pipeline. HandleAsync would skip the behaviours:
var created = await HandlerHarness
    .For<CreateInvoice, int>(new CreateInvoiceHandler(store))
    .WithBehavior(new AuditBehavior<CreateInvoice, int>(log))
    .SendAsync(new CreateInvoice("INV-001", 250m));

var id = created.ShouldSucceed();

// Code that sends, with no container at all:
var sender = new FakeSender()
    .Returns<GetInvoice, InvoiceModel>(new InvoiceModel(1, 250m))
    .Succeeds<CloseInvoice>();

await new NightlyRun(sender).ExecuteAsync(CancellationToken.None);

sender.ShouldHaveSent<CloseInvoice>(request => request.Id == 1);
sender.ShouldNotHaveSent<ArchiveInvoice>();

// A validator on its own, one test per rule:
await validator.ShouldRejectAsync(new CreateInvoice("", 250m), "invoice.reference");
